from common import T

# --- Intervertebral discs -----------------------------------------------------------
LEVELS = ["C2-C3", "C3-C4", "C4-C5", "C5-C6", "C6-C7", "C7-T1"] + [f"T{i}-T{i + 1}" for i in range(1, 12)] + ["T12-L1"] + [f"L{i}-L{i + 1}" for i in range(1, 5)] + ["L5-S1"]
for lv in LEVELS:
    region = "boyun" if lv.startswith("C") else ("göğüs" if lv.startswith("T") else "bel")
    note = {"L4-L5": " Disk hernilerinin en sık görüldüğü iki seviyeden biridir; posterolateral fıtık genellikle L5 kökünü sıkıştırır.",
            "L5-S1": " En sık fıtıklaşan seviyedir; posterolateral fıtık S1 kökünü sıkıştırır (Aşil refleksi azalır).",
            "C5-C6": " Boyun disk hernilerinin en sık seviyesidir; C6 kökü etkilenir.",
            "C6-C7": " Sık fıtıklaşan boyun seviyesidir; C7 kökü etkilenir (triceps refleksi azalır)."}.get(lv, "")
    T(f"Intervertebral disc {lv}", f"{lv} intervertebral diski", f"Discus intervertebralis {lv}",
      f"{lv} omur gövdeleri arasındaki fibrokartilaj disk ({region} bölgesi); dışta anulus fibrosus, içte nucleus pulposus bulunur, yükü dağıtır ve hareket sağlar.{note}")
    T(f"Nucleus pulposus {lv}", f"{lv} nucleus pulposus", f"Nucleus pulposus {lv}",
      f"{lv} diskinin jel kıvamlı merkezi; notokord kalıntısıdır. Anulus fibrosus yırtılınca posterolateral yönde fıtıklaşarak sinir kökünü sıkıştırabilir.")
T("Sacrococcygeal symphysis", "Sakrokoksigeal simfiz", "Symphysis sacrococcygea",
  "Sakrum ucu ile koksiks arasındaki fibrokartilaj eklem; doğumda koksiksin geriye esnemesine izin verir.")

